E('6 the join takes a side',
  'def stmt_join(db, sid, bill_id, rates, who=None):\n    """The supplier\'s bill or estimate (a scanned paper, theirs, not a challan) joined to the statement; the rates typed onto its\n    lines; the lines go to billed. A paper already joined to another statement is refused."""\n    s = next((x for x in stmt_rows(db) if x["id"] == sid), None)\n    if s is None:\n        raise ValueError("That statement is not there.")\n    if s["paid_at"]:\n        raise ValueError("A paid statement is kept as it is.")\n    b = db.execute("SELECT * FROM bills WHERE id=?", (bill_id,)).fetchone()\n    if b is None or b["dup_of"] or b["status"] == "rejected":\n        raise ValueError("Choose the supplier\'s scanned bill or estimate.")\n    if (b["doc_kind"] or "bill") not in ("bill", "estimate"):\n        raise ValueError("%s is a %s — join their bill or estimate, not a challan." % (_stamp_of(b), b["doc_kind"]))\n    if _skey(b["vendor"]) != s["supplier"]:\n        raise ValueError("%s is not this supplier\'s paper." % _stamp_of(b))\n    if any(x["bill_id"] == bill_id and x["id"] != sid for x in stmt_rows(db)):\n        raise ValueError("%s is already joined to another statement." % _stamp_of(b))\n    n = 0\n    for lid, rate in rates.items():\n        if rate is None:\n            continue\n        db.execute("UPDATE stationery_line SET rate=? WHERE id=? AND stmt_id=?", (rate, lid, sid))\n        n += 1\n    db.execute("UPDATE stationery_stmt SET bill_id=?, bill_created_at=?, billed_at=? WHERE id=?", (bill_id, b["created_at"] or "", _now(), sid))\n    _audit(db, "stationery_stmt_billed", {"id": sid, "bill": bill_id, "rates": n})\n    return n\n\n\n',
  'def stmt_join(db, sid, bill_id, rates, who=None, side="clinic"):\n    """The supplier\'s bill or estimate (a scanned paper, theirs, not a challan) joined to the statement; the rates typed onto its\n    lines; the lines go to billed. A paper already joined to a statement is refused.\n    S746 (D845 (4); the owner 07:40 IST 07-Nov-2026: two bills, NK pays its own): side \'clinic\' or \'nk\' -- each side\'s own bill, its\n    rates typed onto THAT side\'s lines only. NK\'s paper sits on the NK Pathology lane (this join moves it there, audited), so it goes\n    into NK\'s accountants\' pack by itself; the Clinic\'s bill is never one on the NK lane."""\n    side = "nk" if side == "nk" else "clinic"\n    pre = "nk_" if side == "nk" else ""\n    s = next((x for x in stmt_rows(db) if x["id"] == sid), None)\n    if s is None:\n        raise ValueError("That statement is not there.")\n    if s[pre + "paid_at"]:\n        raise ValueError("%s\'s bill is paid — kept as it is." % SIDE_WORD[side])\n    if s[pre + "bill_id"]:\n        raise ValueError("%s\'s bill is already joined." % SIDE_WORD[side])\n    if side not in s["sides"]:\n        raise ValueError("This statement has no %s lines." % SIDE_WORD[side])\n    b = db.execute("SELECT * FROM bills WHERE id=?", (bill_id,)).fetchone()\n    if b is None or b["dup_of"] or b["status"] == "rejected":\n        raise ValueError("Choose the supplier\'s scanned bill or estimate.")\n    if (b["doc_kind"] or "bill") not in ("bill", "estimate"):\n        raise ValueError("%s is a %s — join their bill or estimate, not a challan." % (_stamp_of(b), b["doc_kind"]))\n    if _skey(b["vendor"]) != s["supplier"]:\n        raise ValueError("%s is not this supplier\'s paper." % _stamp_of(b))\n    if any(bill_id in (x["bill_id"], x.get("nk_bill_id")) for x in stmt_rows(db)):\n        raise ValueError("%s is already joined to a statement." % _stamp_of(b))\n    lane = b["lane"] or "clinic"\n    if side == "clinic" and lane == "lab_purchase":\n        raise ValueError("%s is on the NK Pathology lane — join it as NK Pathology\'s bill." % _stamp_of(b))\n    if side == "nk" and lane != "lab_purchase":\n        if b["status"] == "approved":\n            raise ValueError("%s is accepted on the clinic lane — it cannot be NK Pathology\'s bill. Choose NK\'s own bill." % _stamp_of(b))\n        kind, status = AR._lane_kind_status("lab_purchase")\n        db.execute("UPDATE bills SET lane=?, kind=?, status=? WHERE id=?", ("lab_purchase", kind, status, bill_id))\n        AR._audit_bill(db, bill_id, "relane", {"from": lane, "to": "lab_purchase", "status": status, "via": "Stationery: NK Pathology\'s bill (S746)"})\n    n = 0\n    for lid, rate in rates.items():\n        if rate is None:\n            continue\n        cur = db.execute("UPDATE stationery_line SET rate=? WHERE id=? AND stmt_id=? AND COALESCE(side,\'clinic\')=?", (rate, lid, sid, side))\n        n += cur.rowcount or 0\n    db.execute("UPDATE stationery_stmt SET %sbill_id=?, %sbill_created_at=?, %sbilled_at=? WHERE id=?" % (pre, pre, pre),\n               (bill_id, b["created_at"] or "", _now(), sid))\n    _audit(db, "stationery_stmt_billed", {"id": sid, "bill": bill_id, "rates": n, "side": side})\n    return n\n\n\n')

E('7 each bill paid on its own',
  'def stmt_paid(db, sid, ref, who=None):\n    s = next((x for x in stmt_rows(db) if x["id"] == sid), None)\n    if s is None:\n        raise ValueError("That statement is not there.")\n    if not s["bill_id"]:\n        raise ValueError("Join the supplier\'s bill or estimate first — a payment is recorded against their paper.")\n    if s["paid_at"]:\n        raise ValueError("Already marked paid.")\n    db.execute("UPDATE stationery_stmt SET paid_at=?, paid_ref=? WHERE id=?", (_now(), re.sub(r"\\s+", " ", ref or "").strip()[:120], sid))\n    _audit(db, "stationery_stmt_paid", {"id": sid, "ref": (ref or "")[:120]})\n\n\n',
  'def stmt_paid(db, sid, ref, who=None, side="clinic"):\n    """S746: each side\'s bill is paid on its own (NK\'s by NK)."""\n    side = "nk" if side == "nk" else "clinic"\n    pre = "nk_" if side == "nk" else ""\n    s = next((x for x in stmt_rows(db) if x["id"] == sid), None)\n    if s is None:\n        raise ValueError("That statement is not there.")\n    if not s[pre + "bill_id"]:\n        raise ValueError("Join %s\'s bill or estimate first — a payment is recorded against their paper." % SIDE_WORD[side])\n    if s[pre + "paid_at"]:\n        raise ValueError("Already marked paid.")\n    db.execute("UPDATE stationery_stmt SET %spaid_at=?, %spaid_ref=? WHERE id=?" % (pre, pre), (_now(), re.sub(r"\\s+", " ", ref or "").strip()[:120], sid))\n    _audit(db, "stationery_stmt_paid", {"id": sid, "ref": (ref or "")[:120], "side": side})\n\n\n')

